namespace RonSijm.FluidHumidifier.Factories.QuickSight;

public class KnowledgeBaseFactory(string resourceName = null, Action<Humidifier.QuickSight.KnowledgeBase> factoryAction = null) : ResourceFactory<Humidifier.QuickSight.KnowledgeBase>(resourceName)
{

    internal List<InnerKnowledgeBaseResourcePermissionFactory> PermissionsFactories { get; set; } = [];

    internal InnerKnowledgeBaseAccessControlConfigurationFactory AccessControlConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseKnowledgeBaseConfigurationFactory KnowledgeBaseConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseMediaExtractionConfigurationFactory MediaExtractionConfigurationFactory { get; set; }

    protected override Humidifier.QuickSight.KnowledgeBase Create()
    {
        var knowledgeBaseResult = CreateKnowledgeBase();
        factoryAction?.Invoke(knowledgeBaseResult);

        return knowledgeBaseResult;
    }

    private Humidifier.QuickSight.KnowledgeBase CreateKnowledgeBase()
    {
        var knowledgeBaseResult = new Humidifier.QuickSight.KnowledgeBase
        {
            GivenName = InputResourceName,
        };

        return knowledgeBaseResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.KnowledgeBase result)
    {
        base.CreateChildren(result);

        result.Permissions = PermissionsFactories.Any() ? PermissionsFactories.Select(x => x.Build()).ToList() : null;
        result.AccessControlConfiguration ??= AccessControlConfigurationFactory?.Build();
        result.KnowledgeBaseConfiguration ??= KnowledgeBaseConfigurationFactory?.Build();
        result.MediaExtractionConfiguration ??= MediaExtractionConfigurationFactory?.Build();
    }

} // End Of Class

