    public static CombinedResult<KnowledgeBaseFactory, InnerKnowledgeBaseResourcePermissionFactory> WithPermissions(this KnowledgeBaseFactory parentFactory, Action<Humidifier.QuickSight.KnowledgeBaseTypes.ResourcePermission> subFactoryAction = null)
    {
        var factory = new InnerKnowledgeBaseResourcePermissionFactory(subFactoryAction);
        parentFactory.PermissionsFactories.Add(factory);
        return CombinedResultFactory.Create(parentFactory, factory);
    }
